<script setup>
import { computed, onBeforeUnmount, ref } from 'vue';
import { Head, Link } from '@inertiajs/vue3';
import AppLayout from '../../Layouts/AppLayout.vue';
import RupiahInput from '../../Components/Shared/RupiahInput.vue';
import Dialog from '../../Components/Shared/Dialog.vue';
import { money } from '../../Support/cart.js';
import { postJson } from '../../Support/request.js';
defineOptions({ layout: AppLayout });
const props = defineProps({ storeName: String, lookupUrl: String, completeUrl: String, backUrl: String });
const completedNow = ref(false); const keepChange = ref(false);
const input = ref(''); const scannedCode = ref(''); const order = ref(null); const cash = ref(''); const error = ref(''); const busy = ref(false); const scanning = ref(false); const video = ref(null); const confirm = ref(false); let controls; let disposed = false; let generation = 0;
const stop = () => { generation++; controls?.stop(); controls = null; video.value?.srcObject?.getTracks().forEach(track => track.stop()); scanning.value = false; };
const lookup = async (value = input.value) => {
    if (busy.value) return;
    stop(); completedNow.value = false; busy.value = true; error.value = ''; order.value = null; cash.value = ''; keepChange.value = false; scannedCode.value = '';
    try { const result = await postJson(props.lookupUrl, { code: value }); if (disposed) return; order.value = result.order; scannedCode.value = value; input.value = ''; }
    catch (exception) { error.value = exception.message; } finally { busy.value = false; }
};
const start = async () => {
    stop(); error.value = ''; order.value = null;
    if (!window.isSecureContext || !navigator.mediaDevices?.getUserMedia) { error.value = 'Camera access requires HTTPS or localhost. You can enter the pickup code below.'; return; }
    const session = generation; scanning.value = true;
    try {
        const { BrowserQRCodeReader } = await import('@zxing/browser');
        if (disposed || session !== generation) return;
        const reader = new BrowserQRCodeReader();
        const active = await reader.decodeFromConstraints({ video: { facingMode: { ideal: 'environment' } }, audio: false }, video.value, (result, decodeError, activeControls) => { if (result && !disposed && session === generation) { activeControls.stop(); lookup(result.getText()); } });
        if (disposed || session !== generation) active.stop(); else controls = active;
    } catch { if (disposed || session !== generation) return; stop(); error.value = 'Camera could not start. Allow camera permission or enter the pickup code below.'; }
};
onBeforeUnmount(() => { disposed = true; stop(); });
const needsCash = computed(() => order.value?.payment_method === 'cash' && order.value?.payment_status === 'unpaid');
const canComplete = computed(() => order.value?.status === 'ready' && (order.value.payment_status === 'paid' || (needsCash.value && Number.isInteger(Number(cash.value)) && cash.value !== '' && Number(cash.value) >= order.value.total)));
const submit = async () => {
    busy.value = true; error.value = '';
    try { const result = await postJson(props.completeUrl, { code: scannedCode.value, keep_change: keepChange.value, cash_received: needsCash.value ? cash.value : null }); order.value = result.order; completedNow.value = true; confirm.value = false; }
    catch (exception) { error.value = exception.message; } finally { busy.value = false; }
};
</script>
<template><Head title="Scan pickup"/><div class="mx-auto max-w-3xl"><Link :href="backUrl" class="text-sm text-stone-500 underline">← My store</Link><p class="mt-6 text-xs text-stone-500">{{ storeName }}</p><h1 class="mt-2 text-3xl font-semibold">Collect an order.</h1><p class="mt-3 text-sm leading-6 text-stone-500">Scan the customer’s pickup QR using your laptop or phone camera, or enter their pickup code.</p><section class="mt-6 rounded-3xl border border-stone-200 bg-white p-6"><div class="flex gap-3"><button type="button" :disabled="busy || scanning" class="rounded-full bg-[#504941] px-5 py-3 text-sm text-white disabled:opacity-40" @click="start">Start camera</button><button v-if="scanning" type="button" class="rounded-full border border-stone-300 px-5 py-3 text-sm" @click="stop">Stop camera</button></div><video ref="video" v-show="scanning" autoplay muted playsinline class="mt-5 aspect-video w-full rounded-2xl bg-stone-900 object-cover"/><form class="mt-5 flex flex-wrap items-end gap-3" @submit.prevent="lookup()"><label class="min-w-48 flex-1 text-sm font-medium">Pickup code<input v-model="input" required maxlength="80" autocomplete="off" spellcheck="false" placeholder="XXXX XXXX XXXX XXXX" class="mt-2 w-full rounded-xl border border-stone-300 px-4 py-3 font-mono uppercase"/></label><button :disabled="busy" class="rounded-full border border-stone-300 px-5 py-3 text-sm disabled:opacity-40">{{ busy ? 'Checking…' : 'Find order' }}</button></form></section><p v-if="error && !confirm" role="alert" class="mt-5 rounded-xl bg-red-50 p-4 text-sm text-red-700">{{ error }}</p><section v-if="order" class="mt-6 rounded-3xl border border-stone-200 bg-white p-6"><template v-if="order.status === 'completed'"><p role="status" class="rounded-xl bg-green-50 p-4 text-sm font-semibold text-green-800">✓ {{ completedNow ? 'Order collected' : 'Order already collected' }} · Payment received</p><p class="mt-4 text-sm">{{ order.reference }} · {{ order.customer_name }}</p><p v-if="order.cash_received !== null" class="mt-3 text-sm">Cash received {{ money(order.cash_received) }} · Change {{ money(order.cash_change) }}</p></template><template v-else><p class="font-mono text-sm font-semibold">{{ order.reference }}</p><h2 class="mt-3 text-xl font-semibold">{{ order.customer_name }}</h2><p class="mt-2 text-sm text-stone-500">{{ order.phone }} · Pickup · {{ order.payment_status === 'paid' ? 'Paid' : 'Unpaid' }}</p><div class="mt-5 space-y-4 border-y border-stone-100 py-5"><div v-for="(item,index) in order.items" :key="index"><p class="text-sm font-medium">{{ item.quantity }} × {{ item.name }} · {{ money(item.line_total) }}</p><p class="mt-1 text-xs text-stone-500">{{ item.choices.map(choice => `${choice.group}: ${choice.name}`).join(' · ') }}</p></div></div><p class="mt-5 flex justify-between text-lg font-semibold"><span>{{ needsCash ? 'Cash due' : 'Order total' }}</span><span>{{ money(order.total) }}</span></p><div v-if="needsCash" class="mt-5"><RupiahInput v-model="cash" name="pickup-cash" label="Cash received" required/><p v-if="cash !== '' && Number(cash) < order.total" class="mt-3 text-sm text-red-700">Cash received is less than the total.</p><label class="mt-3 flex items-center gap-2 text-sm"><input v-model="keepChange" type="checkbox">Customer leaves the change</label><p v-if="cash !== '' && Number(cash) >= order.total" class="mt-3 flex justify-between rounded-xl bg-stone-50 p-4 text-sm"><span>Change</span><strong>{{ money(keepChange ? 0 : Number(cash) - order.total) }}</strong></p></div><p v-else-if="order.payment_status === 'paid'" class="mt-4 text-sm text-green-800">Payment is already received. Confirm collection without charging again.</p><p v-else class="mt-4 text-sm text-amber-800">This bank transfer has not been verified. Complete payment verification before handing over the order.</p><button type="button" :disabled="!canComplete || busy" class="mt-6 w-full rounded-full bg-[#504941] px-5 py-3 text-sm font-semibold text-white disabled:opacity-40" @click="confirm = true">{{ needsCash ? 'Confirm cash & collection' : 'Confirm collection' }}</button></template></section></div><Dialog :open="confirm" title="Confirm collection" :busy="busy" @close="confirm = false"><p class="text-sm leading-6">Hand over {{ order?.reference }} to {{ order?.customer_name }} and mark it completed?</p><p v-if="needsCash" class="mt-4 text-sm">Cash received {{ money(cash) }} · Change {{ money(keepChange ? 0 : Number(cash) - order.total) }}</p><p v-if="error" role="alert" class="mt-4 text-sm text-red-700">{{ error }}</p><div class="mt-6 flex justify-end gap-3"><button :disabled="busy" type="button" class="rounded-full border border-stone-300 px-4 py-3 text-sm" @click="confirm = false">Back</button><button :disabled="busy" type="button" class="rounded-full bg-[#504941] px-5 py-3 text-sm text-white" @click="submit">{{ busy ? 'Saving…' : 'Confirm & complete' }}</button></div></Dialog></template>
